<div class="gamification-admin-head"><div><a href="<?php echo url('admin/teams') ?>"><?php echo icon('fas fa-arrow-left') ?> <?php echo $this->lang('Teams') ?></a><h2><?php echo utf8_htmlentities($team['title']) ?></h2></div><?php echo $this->button_create('admin/teams/members/'.$team['team_id'].'/add', (string)$this->lang('Add member')) ?></div>
<div class="table-responsive"><table class="table"><thead><tr><th><?php echo $this->lang('Member') ?></th><th><?php echo $this->lang('Role') ?></th><th><?php echo $this->lang('Steam ID') ?></th><th><?php echo $this->lang('Actions') ?></th></tr></thead><tbody><?php foreach ($members as $member): ?><tr><td><?php echo utf8_htmlentities($member['display_name']) ?><?php if ($member['captain']): ?> <span class="badge badge-primary"><?php echo $this->lang('Captain') ?></span><?php endif ?></td><td><?php echo utf8_htmlentities($member['role']) ?></td><td><?php echo utf8_htmlentities($member['steam_id'] ?? '') ?></td><td><?php echo $this->button_update('admin/teams/members/edit/'.$member['member_id']) ?><?php echo $this->button_delete('admin/teams/members/delete/'.$member['member_id']) ?></td></tr><?php endforeach ?></tbody></table></div>
